head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[selectbox > P > valueNotInList]<br/>아이템 리스트에 없는 아이템을 선택했을때 처리하는 방식을 설정합니다.",
    "validation" : [        
        "renderType=component 인 경우에 동작합니다.",
        "미설정 시 emptyItem 속성값에 따라 아이템이 선택되지 않거나 첫번째 아이템이 선택됩니다.",
        "keepValue 설정 시 임시로 SelectBox 컴포넌트의 Value 값과 아이템 표시 영역엔 선택된 값이 설정되고 Label 값은 null 로 설정됩니다.",
        "keepValue 설정 시 아이템 리스트에는 추가되지 않으며 getSelectedIndex() 메소드 실행 시 -1 을 반환하고 getValue() 메소드 실행 시 Value 값을 반환합니다.",
        "default 설정 시 emptyItem 속성값에 따라 아이템이 선택되지 않거나 첫번째 아이템이 선택됩니다.",
        "아이템 리스트에는 추가되지 않으며 getSelectedIndex() 메소드 실행 시 -1 을 반환하고 getValue() 메소드 실행 시 Value 값을 반환합니다.",
        "setText(), setSelectedIndex() 메소드로 없는 아이템을 선택하면 Value 값이 ''(Emtpy String)으로 설정됩니다.",
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {                
        emptyItem : con_emptyItem.getText(),
        valueNotInList : con_valueNotInList.getText(),
    }

    let cList = $c.gcm.createCList(properties)

    // target 생성    
    $c.gcm.createBasicSelectBox(cList);
}



scwin.btn_setValue_onclick = function (e) {
	target1.setValue(100);
    scwin.btn_getInfo_onclick();
};



scwin.btn_setSelectedIndex_onclick = function (e) {
	target1.setSelectedIndex(100);
    scwin.btn_getInfo_onclick();
};



scwin.btn_setText_onclick = function (e) {
	target1.setText("invalid");
    scwin.btn_getInfo_onclick();	
};



scwin.btn_getInfo_onclick = function (e) {
    let rtn = '';

    rtn = target1.getText();
	wf_body_bottom.getObj("scwin").setReturnValue("getText : " + rtn);

    rtn = target1.getValue();
	wf_body_bottom.getObj("scwin").setReturnValue("getValue : " + rtn);    

    rtn = target1.getSelectedIndex();
	wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex : " + rtn);
};
